//! Dynamic product-catalog renderer for the `/software` storefront page.
//!
//! This module renders the marketplace catalog **from the same [`crate::Catalog`]
//! data that `v1_products` serves** — there is no second source of truth for real
//! products. Because the cards are generated by iterating the loaded catalog, the
//! page can never drift from `products.yaml`.
//!
//! **Phase 1b, holistic redesign.** Two structural decisions replace the earlier
//! (2026-07-07-ratified) two-shelf Commercial/Open-Source model:
//!
//! 1. **Architecture tiers (Infrastructure/Platform/Delivery) are now the page's
//!    only grouping axis**, in a deliberately Delivery-first order (see
//!    `TIER_ORDER`'s doc comment). License tier is not lost — it moves into each
//!    real card's derived "Distribution" fact row and stays fully explorable via
//!    `/licensing` — it's demoted from primary axis to per-card attribute. The
//!    two-shelf model currently rendered only one populated shelf anyway (zero
//!    `Apache`-tier products exist in `products.yaml`), so this costs no live
//!    structure.
//! 2. **Real products and roadmap items now share one page**, via the [`TierCard`]
//!    enum below. An earlier design rendered the roadmap as a structurally separate
//!    `/roadmap` page after an adversarial review found real risks in mixing them
//!    (drift, honesty, complexity). The operator later reviewed that shipped result
//!    and directed a merge. The two safety properties that review named survive,
//!    now enforced by a **type + module boundary** instead of a URL boundary:
//!    - **No drift**: `TierCard::Real` can only be built from a borrow into the
//!      loaded `Catalog`; `TierCard::Roadmap` can only be built from
//!      `roadmap::ROADMAP_ITEMS`, a `pub(crate)` const that never touches
//!      `products.yaml`. There is no third, hand-authored source — a card not
//!      built from one of these two is a compile error, not a discipline problem.
//!    - **No fake purchase signal**: `roadmap::roadmap_item_card` has no access to
//!      this module's `install_command`/`download_command`/checkout-link builder/
//!      `json_ld_script` — all private here. A roadmap card is *structurally
//!      incapable* of emitting a price, install/download block, or checkout link.
//!      `roadmap.rs`'s own tests guard this per-card; this module's
//!      `every_roadmap_card_on_the_merged_page_is_purchase_free` guards it again on
//!      the actual merged page.
//!
//! See `.agent/briefs/BRIEF-storefront-architecture-education.md` for the full
//! research trail (three design iterations, real competitor research, an
//! adversarial review) behind this shape.
//!
//! Fields NOT available in the catalog (noted rather than fabricated):
//!   - **sha256** — no SHA field exists on `Installer`. Per-artifact SHA256 lives on
//!     the release server's per-version `MANIFEST` endpoint, not in `products.yaml`.
//!
//! Pricing units: `price_usdc` is USDC base units (6 decimals), verified against
//! `tool-wallet/src/main.rs` (`$1.00 USDC = 1_000_000 units`). Displayed dollars are
//! `price_usdc as f64 / 1_000_000.0`.

use crate::ui::roadmap::{self, RoadmapItem};
use crate::ui::Lang;
use crate::{ArchTier, ArtifactKind, LicenseTier};
use maud::{html, Markup, PreEscaped};

/// One slot in a tier section's grid. The two variants are the page's only two data
/// sources, and there is deliberately no third — see this module's doc comment.
enum TierCard<'a> {
    Real(&'a crate::Installer),
    Roadmap(&'static RoadmapItem),
}

/// Page order: Delivery first, Platform second, Infrastructure last — a deliberate,
/// explicit inversion of `project-totebox/README.md`'s own bottom-up engineering
/// table. A storefront meets a visitor top-down, at the surface closest to what
/// they'll actually touch, not at the foundation underneath it. It also avoids
/// opening the page on the one tier with zero real, downloadable products today
/// (Infrastructure) — locked in via `tier_sections_render_in_delivery_platform_
/// infrastructure_order` below so a future "fix" doesn't silently revert it.
const TIER_ORDER: [ArchTier; 3] = [
    ArchTier::Delivery,
    ArchTier::Platform,
    ArchTier::Infrastructure,
];

/// Real products in this tier, then roadmap items in this tier — never
/// interleaved, never alphabetical. A visitor should read "here's what you can
/// have today" before "here's where this layer is going."
fn tier_cards<'a>(catalog: &'a crate::Catalog, tier: ArchTier) -> Vec<TierCard<'a>> {
    let mut cards: Vec<TierCard<'a>> = catalog
        .installers
        .iter()
        .filter(|i| i.tier == tier)
        .map(TierCard::Real)
        .collect();
    cards.extend(
        roadmap::ROADMAP_ITEMS
            .iter()
            .filter(|r| r.tier == tier)
            .map(TierCard::Roadmap),
    );
    cards
}

/// Build the curl-pipe-sh install command for a bare-binary product.
fn install_command(source_base_url: &str, id: &str) -> String {
    let base = source_base_url.trim_end_matches('/');
    format!("curl -fsSL {base}/{id}/install.sh | bash")
}

/// A dark terminal-style install-command block with a copy-to-clipboard button.
fn install_block(command: &str, lang: Lang) -> Markup {
    let l = lang.catalog_labels();
    html! {
        div."sw-cat-install" {
            div."sw-cat-cmd" {
                code."sw-cat-cmd__text" { (command) }
                button."sw-cat-cmd__copy" type="button"
                    data-sw-clip=(command) data-sw-label=(l.copy)
                    aria-label=(l.copy_aria) { (l.copy) }
            }
            p."sw-cat-hint" { (l.install_hint) }
        }
    }
}

/// Build the direct-download curl command for an `ArtifactKind::ApplianceImage`
/// product — there is nothing to "install" (curl-pipe-sh into bash makes no sense
/// for a boot image), so this just fetches the file to disk.
fn download_command(source_base_url: &str, id: &str, edition: &str, platform_slug: &str) -> String {
    let base = source_base_url.trim_end_matches('/');
    format!("curl -fsSL {base}/{id}/{edition}/{platform_slug} -o {platform_slug}")
}

/// The appliance-image counterpart to `install_block`.
fn download_block(command: &str, lang: Lang) -> Markup {
    let l = lang.catalog_labels();
    html! {
        div."sw-cat-install" {
            div."sw-cat-cmd" {
                code."sw-cat-cmd__text" { (command) }
                button."sw-cat-cmd__copy" type="button"
                    data-sw-clip=(command) data-sw-label=(l.copy)
                    aria-label=(l.copy_aria) { (l.copy) }
            }
            p."sw-cat-hint" { (l.download_hint) }
        }
    }
}

/// How this product's artifact is distributed — one clause of the derived
/// "Distribution" fact row (`card_fact_rows`), never authored in `products.yaml`.
fn artifact_label(kind: ArtifactKind) -> &'static str {
    match kind {
        ArtifactKind::CliBinary => "Native binary",
        ArtifactKind::ApplianceImage => "Appliance image",
    }
}

/// A real product's fact-row block: up to 3 authored facts from `products.yaml`,
/// plus a 4th, always-derived "Distribution" row (artifact kind/size/edition/
/// license) computed here, never authored — it can't drift from the rest of this
/// struct's own fields. Reuses `roadmap::fact_rows` verbatim — the same visual
/// contract real and roadmap cards share.
fn card_fact_rows(i: &crate::Installer) -> Markup {
    let distribution = format!(
        "{} \u{b7} {} MB \u{b7} {}",
        artifact_label(i.artifact),
        i.size_mb,
        i.license_tier.label()
    );
    let mut pairs: Vec<(&str, &str)> = i
        .facts
        .iter()
        .map(|f| (f.label.as_str(), f.value.as_str()))
        .collect();
    pairs.push(("DISTRIBUTION", distribution.as_str()));
    roadmap::fact_rows(&pairs)
}

/// The status row shared by every real card: an "Available now"/BETA-free/open-
/// source chip plus the version chip. Reuses `.sw-cat-status`/`.sw-cat-chip` — the
/// same visual language `roadmap::status_block` uses for "Not yet available", so a
/// visitor reads both card kinds as the same *kind* of thing, distinguished only by
/// which chip they carry.
fn real_status_row(i: &crate::Installer, lang: Lang) -> Markup {
    let l = lang.catalog_labels();
    let chip = if i.license_tier == LicenseTier::Apache {
        l.free_open_source
    } else if i.price_usdc == 0 {
        l.beta_free
    } else {
        l.available_now
    };
    html! {
        div."sw-cat-status" {
            span."sw-cat-chip" { (chip) }
            span."sw-cat-badge sw-cat-badge--ver" { "v" (i.edition) }
            span."sw-cat-badge" { (i.family.label()) }
        }
    }
}

/// Every real card's name links to its product-detail page — a real gap fixed in
/// Phase 1b (cards previously linked nowhere at all).
fn card_name_link(i: &crate::Installer, lang: Lang) -> Markup {
    html! {
        h3."sw-cat-card__name" {
            a href=(lang.localize(&format!("/software/{}", i.id))) { (i.name) }
        }
    }
}

fn becomes_line(i: &crate::Installer) -> Option<Markup> {
    i.becomes.as_ref().map(|b| {
        html! {
            p."sw-cat-card__becomes" { (b) }
        }
    })
}

/// A free/BETA product card — `price_usdc == 0`. Real curl-pipe-sh install
/// command, no payment step.
fn free_product_card(i: &crate::Installer, source_base_url: &str, lang: Lang) -> Markup {
    let command = install_command(source_base_url, &i.id);
    html! {
        article."sw-cat-card" {
            span."sw-cat-card__id" { (i.id) }
            (card_name_link(i, lang))
            @if let Some(becomes) = becomes_line(i) { (becomes) }
            p."sw-cat-card__desc" { (i.description) }
            (real_status_row(i, lang))
            (card_fact_rows(i))
            (install_block(&command, lang))
        }
    }
}

/// An `ArtifactKind::ApplianceImage` product card — a copy of `free_product_card`
/// with the curl-pipe-sh install block swapped for a direct-download block.
fn appliance_product_card(i: &crate::Installer, source_base_url: &str, lang: Lang) -> Markup {
    let command = download_command(source_base_url, &i.id, &i.edition, i.platform_slug());
    html! {
        article."sw-cat-card" {
            span."sw-cat-card__id" { (i.id) }
            (card_name_link(i, lang))
            @if let Some(becomes) = becomes_line(i) { (becomes) }
            p."sw-cat-card__desc" { (i.description) }
            (real_status_row(i, lang))
            (card_fact_rows(i))
            (download_block(&command, lang))
        }
    }
}

/// A paid product card — `price_usdc > 0` (BETA lifted for this product). Shows the
/// price and a Polygon-USDC pay CTA in place of the install/download terminal.
fn paid_product_card(i: &crate::Installer, lang: Lang) -> Markup {
    let dollars = i.price_usdc as f64 / 1_000_000.0;
    let checkout_href = format!("/checkout/{}", i.id);
    let l = lang.catalog_labels();
    let pay_aria = l.pay_aria_fmt.replace("{}", &i.name);
    html! {
        article."sw-cat-card" {
            span."sw-cat-card__id" { (i.id) }
            (card_name_link(i, lang))
            @if let Some(becomes) = becomes_line(i) { (becomes) }
            p."sw-cat-card__desc" { (i.description) }
            (real_status_row(i, lang))
            (card_fact_rows(i))
            div."sw-cat-price" {
                span."sw-cat-price__amt" { "$" (format!("{dollars:.2}")) }
                span."sw-cat-price__unit" { (l.price_unit) }
                div."sw-cat-pay" {
                    a."sw-cat-pay__cta" href=(checkout_href)
                        rel="nofollow" aria-label=(pay_aria) {
                        span."sw-cat-pay__mark" aria-hidden="true" { "\u{25C8}" }
                        (l.pay_cta)
                    }
                    p."sw-cat-pay__meta" { (l.pay_meta) }
                }
            }
        }
    }
}

/// Simple geometric glyphs distinguishing the 3 tiers — same lightweight-Unicode
/// approach this crate already uses elsewhere (`pay_cta`'s "\u{25C8}" mark,
/// roadmap's "\u{2192}" arrow), not hand-rolled SVG.
fn tier_glyph(tier: ArchTier) -> &'static str {
    match tier {
        ArchTier::Delivery => "\u{25b4}", // outward — what people touch
        ArchTier::Platform => "\u{2261}", // stacked layers — what runs and stores
        ArchTier::Infrastructure => "\u{25ac}", // a base — what it all stands on
    }
}

fn tier_blurb(tier: ArchTier, lang: Lang) -> &'static str {
    match (tier, lang) {
        (ArchTier::Delivery, Lang::En) =>
            "What people actually sit in front of \u{2014} the surfaces staff and operators use every day.",
        (ArchTier::Platform, Lang::En) =>
            "What runs and stores the work \u{2014} the archives, brokers, and command servers a deployment is assembled from.",
        (ArchTier::Infrastructure, Lang::En) =>
            "What the whole thing stands on \u{2014} the host layer that keeps a deployment on hardware you control.",
        (ArchTier::Delivery, Lang::Es) =>
            "Lo que su personal realmente utiliza \u{2014} las superficies que operadores y personal usan cada d\u{ed}a.",
        (ArchTier::Platform, Lang::Es) =>
            "Lo que ejecuta y almacena el trabajo \u{2014} los archivos, corredores y servidores de comando de un despliegue.",
        (ArchTier::Infrastructure, Lang::Es) =>
            "Sobre lo que se apoya todo \u{2014} la capa de host que mantiene un despliegue en hardware que usted controla.",
    }
}

