/// `SoftwareApplication` JSON-LD for `/software` — page-level, generic (never
/// per-product), which is exactly why a roadmap card can never carry one: this is
/// the only place this module emits it, and `roadmap.rs` has no access to it.
fn json_ld_script() -> Markup {
    let json = r#"{"@context":"https://schema.org","@type":"SoftwareApplication","name":"PointSav Software Marketplace","applicationCategory":"BusinessApplication","provider":{"@type":"Organization","@id":"https://pointsav.com/#organization"}}"#;
    html! {
        script type="application/ld+json" { (PreEscaped(json)) }
    }
}

/// Vanilla-JS copy-to-clipboard for every `[data-sw-clip]` control.
fn clipboard_script(lang: Lang) -> Markup {
    let copied = lang.catalog_labels().copied;
    let js = format!(
        r#"(function(){{
document.querySelectorAll('[data-sw-clip]').forEach(function(btn){{
  btn.addEventListener('click',function(){{
    var text=btn.getAttribute('data-sw-clip');
    if(!navigator.clipboard){{return;}}
    navigator.clipboard.writeText(text).then(function(){{
      var label=btn.getAttribute('data-sw-label')||btn.textContent;
      btn.textContent='{copied}';
      setTimeout(function(){{btn.textContent=label;}},1500);
    }}).catch(function(){{}});
  }});
}});
}})();"#
    );
    html! { script { (PreEscaped(js)) } }
}

fn tier_section(
    tier: ArchTier,
    catalog: &crate::Catalog,
    source_base_url: &str,
    lang: Lang,
) -> Markup {
    let cards = tier_cards(catalog, tier);
    let real_count = cards
        .iter()
        .filter(|c| matches!(c, TierCard::Real(_)))
        .count();
    let planned_count = cards.len() - real_count;
    let (count_text, also_h) = match lang {
        Lang::En => (
            match (real_count, planned_count) {
                (r, 0) => format!("{r} available"),
                (0, p) => format!("{p} planned"),
                (r, p) => format!("{r} available \u{b7} {p} planned"),
            },
            "Also in this tier \u{2014} not yet available",
        ),
        Lang::Es => (
            match (real_count, planned_count) {
                (r, 0) => format!("{r} disponibles"),
                (0, p) => format!("{p} planificados"),
                (r, p) => format!("{r} disponibles \u{b7} {p} planificados"),
            },
            "Tambi\u{e9}n en esta capa \u{2014} a\u{fa}n no disponible",
        ),
    };
    html! {
        @if !cards.is_empty() {
            section."sw-cat-section" id=(tier.slug()) {
                h2."sw-cat-section__h" {
                    span."sw-cat-section__glyph" aria-hidden="true" { (tier_glyph(tier)) }
                    (tier.label())
                    span."sw-cat-section__count" { (count_text) }
                }
                p."sw-cat-section__blurb" { (tier_blurb(tier, lang)) }
                hr."sw-cat-section__underline";
                div."sw-cat-grid" {
                    @for card in &cards {
                        @match card {
                            TierCard::Real(i) if i.artifact == ArtifactKind::ApplianceImage => {
                                (appliance_product_card(i, source_base_url, lang))
                            }
                            TierCard::Real(i) if i.price_usdc == 0 => {
                                (free_product_card(i, source_base_url, lang))
                            }
                            TierCard::Real(i) => {
                                (paid_product_card(i, lang))
                            }
                            TierCard::Roadmap(_) => {}
                        }
                    }
                    @if real_count > 0 && planned_count > 0 {
                        p."sw-cat-subhead" { (also_h) }
                    }
                    @for card in &cards {
                        @if let TierCard::Roadmap(r) = card {
                            (roadmap::roadmap_item_card(r, lang))
                        }
                    }
                }
            }
        }
    }
}

/// Render the full product catalog as body content for the `/software` page. See
/// this module's doc comment for the Phase 1b architecture (arch-tier grouping,
/// merged real+roadmap cards).
pub fn catalog_markup(catalog: &crate::Catalog, source_base_url: &str, lang: Lang) -> Markup {
    let l = lang.catalog_labels();
    let real_count = catalog.installers.len();
    let roadmap_count = roadmap::ROADMAP_ITEMS.len();

    let (
        trust_items,
        stat_available,
        stat_roadmap,
        stat_purchase,
        archband_h,
        archband_deck,
        footer_licensing,
        footer_roadmap_note,
        footer_contact,
        honesty,
    ) = match lang {
        Lang::En => (
            [
                "No subscription",
                "No cloud dependency",
                "No kill switch",
                "Your keys, your license",
            ],
            "Available to download today",
            "In design or active development",
            "One-time purchase, no subscription",
            "One stack, three layers",
            "The components of an orchestration, not an app store. What's ready has \
             a download command below it; what's still being built has a status \
             label instead \u{2014} and isn't for sale yet.",
            "Licensing \u{2014} every tier, in plain terms",
            "Roadmap \u{2014} marked in each tier above",
            "Contact \u{2014} talk to a human",
            "This catalog always matches what's actually available to download \
             \u{2014} nothing here is stale or hand-curated.",
        ),
        Lang::Es => (
            [
                "Sin suscripci\u{f3}n",
                "Sin dependencia de la nube",
                "Sin interruptor de apagado remoto",
                "Sus claves, su licencia",
            ],
            "Disponibles para descargar hoy",
            "En dise\u{f1}o o desarrollo activo",
            "Compra \u{fa}nica, sin suscripci\u{f3}n",
            "Una plataforma, tres capas",
            "Los componentes de una orquestaci\u{f3}n, no una tienda de aplicaciones. \
             Lo que ya est\u{e1} listo tiene un comando de descarga debajo; lo que \
             a\u{fa}n se est\u{e1} construyendo tiene una etiqueta de estado en su \
             lugar \u{2014} y todav\u{ed}a no est\u{e1} a la venta.",
            "Licencias \u{2014} cada nivel, en t\u{e9}rminos sencillos",
            "Hoja de ruta \u{2014} marcado en cada capa arriba",
            "Contacto \u{2014} hable con una persona",
            "Este cat\u{e1}logo siempre coincide con lo que realmente est\u{e1} \
             disponible para descargar \u{2014} nada aqu\u{ed} est\u{e1} \
             desactualizado ni curado a mano.",
        ),
    };

    html! {
        (catalog_style())
        (json_ld_script())
        div."sw-cat-wrap" {
            p."sw-cat-eyebrow" { (l.eyebrow) }
            h1."sw-cat-intro" { (l.title) }
            p."sw-cat-lede" { (l.lede) }
            div."sw-cat-trust" {
                @for (n, item) in trust_items.iter().enumerate() {
                    @if n > 0 { span aria-hidden="true" { "\u{b7}" } }
                    span { (item) }
                }
            }
            div."sw-cat-stats" {
                div."sw-cat-stat" {
                    span."sw-cat-stat__num" { (real_count) }
                    span."sw-cat-stat__label" { (stat_available) }
                }
                div."sw-cat-stat" {
                    span."sw-cat-stat__num" { (roadmap_count) }
                    span."sw-cat-stat__label" { (stat_roadmap) }
                }
                div."sw-cat-stat" {
                    span."sw-cat-stat__label sw-cat-stat__label--standalone" { (stat_purchase) }
                }
            }
            div."sw-cat-archband" {
                h2."sw-cat-archband__h" { (archband_h) }
                p."sw-cat-archband__deck" { (archband_deck) }
                div."sw-cat-archband__tiles" {
                    @for tier in TIER_ORDER {
                        a."sw-cat-archtile" href=(format!("#{}", tier.slug())) {
                            span."sw-cat-archtile__glyph" aria-hidden="true" { (tier_glyph(tier)) }
                            span."sw-cat-archtile__name" { (tier.label()) }
                            p."sw-cat-archtile__blurb" { (tier_blurb(tier, lang)) }
                        }
                    }
                }
            }
            @for tier in TIER_ORDER {
                (tier_section(tier, catalog, source_base_url, lang))
            }
            div."sw-cat-footerband" {
                a href=(lang.localize("/licensing")) { (footer_licensing) }
                span { (footer_roadmap_note) }
                a href=(lang.localize("/page/contact")) { (footer_contact) }
            }
            p."sw-cat-honesty" { (honesty) }
        }
        (clipboard_script(lang))
    }
}

